function authView(){let setup=setupInfo?.needsSetup;return `<div class="auth-screen"><div class="auth-card"><img src="assets/osp-8-ball.png" alt="OSP Billiards logo"><div class="eyebrow">OSP BILLIARDS PLAY</div><h1>${setup?'Set up the first venue':'Sign in'}</h1><p class="muted">${setup?'The site owner signs in once to create the first administrator.':'Enter your account. The site automatically opens the correct player or administrator area.'}</p>${authError?`<div class="notice warn">${esc(authError)}</div>`:''}${setup&&!setupInfo.owner?'<a class="btn primary" href="/signin-with-chatgpt?return_to=/" target="_top">Site owner: sign in to set up</a>':`<form id="auth-form" class="auth-form">${setup?`<div class="field"><label>Venue name</label><input name="groupName" required maxlength="80"></div><div class="field"><label>Your name</label><input name="name" required></div>`:''}<div class="field"><label>Username${setup?' (unique)':' / email / phone'}</label><input name="${setup?'username':'identifier'}" required autocomplete="username" autocapitalize="none" spellcheck="false"></div>${setup?'<div class="field"><label>Email (optional)</label><input name="email" type="email"></div><div class="field"><label>Phone (optional)</label><input name="phone" type="tel" inputmode="tel"></div>':''}<div class="field"><label>Password (8+ characters; digits allowed)</label><input id="login-password" name="password" type="password" minlength="8" required autocomplete="${setup?'new-password':'current-password'}"><label class="inline-help"><input type="checkbox" data-action="toggle-password"> Show password</label></div><button class="btn primary" type="submit">${setup?'Create venue':'Sign in'}</button></form>`}${requestAccessView()}${!setup&&setupInfo?.owner?`<div class="divider"></div><button class="btn ghost" data-action="show-recovery">Recover administrator access</button>${showRecovery?`<section class="recovery">${ownerVenues.some(x=>x.account_id)?`<h2>Reset an administrator password</h2><form id="recover-form" class="auth-form"><div class="field"><label>Venue and administrator</label><select name="accountId" required>${ownerVenues.filter(x=>x.account_id).map(x=>`<option value="${esc(x.account_id)}" data-group="${esc(x.group_id)}">${esc(x.venue)} · ${esc(x.name)} (@${esc(x.username)})</option>`).join('')}</select></div><div class="field"><label>New password (8+ characters)</label><input name="password" type="password" minlength="8" required autocomplete="new-password"></div><button class="btn primary">Reset password</button></form>`:''}${ownerVenues.some(x=>!x.account_id)?`<h2>Finish administrator setup</h2><p class="inline-help">This venue was created without an administrator. Add one here without losing the venue.</p><form id="repair-admin-form" class="auth-form"><div class="field"><label>Venue</label><select name="groupId" required>${ownerVenues.filter(x=>!x.account_id).map(x=>`<option value="${esc(x.group_id)}">${esc(x.venue)}</option>`).join('')}</select></div>${accountFields()}<button class="btn primary">Create administrator and sign in</button></form>`:''}</section>`:''}<div class="divider"></div><h2>Create another venue</h2><p class="inline-help">Create administrator 2 with its own venue and player list.</p><form id="owner-venue-form" class="auth-form"><div class="field"><label>Venue name</label><input name="groupName" required maxlength="80"></div>${accountFields()}<button class="btn primary">Create venue and sign in</button></form>`:''}</div></div>`}
function accessRequestsView(){return `<section class="card"><h2>Account and password requests ${accessRequests.length?`(${accessRequests.length})`:''}</h2><p class="inline-help">Verify the person's identity using their contact details before creating an account or resetting a password. Then mark the request complete.</p><div class="list">${accessRequests.map(r=>`<div class="row"><div class="row-main"><strong>${esc(r.name)} · ${r.kind==='player_signup'?'Player account':'Password reset'}</strong><small>${new Date(r.created_at).toLocaleString()} · ${esc(r.username?`@${r.username} · `:'')}${esc(r.email)} ${esc(r.phone)}</small>${r.message?`<div>${esc(r.message)}</div>`:''}</div>${r.kind==='player_signup'?`<button class="btn small primary" data-action="create-request-player" data-id="${esc(r.id)}">Create player</button>`:`<button class="btn small" data-tab="access">Accounts</button>`}<button class="btn small ghost" data-action="access-request-status" data-id="${esc(r.id)}" data-status="resolved">Done</button><button class="btn small ghost" data-action="access-request-status" data-id="${esc(r.id)}" data-status="dismissed">Dismiss</button></div>`).join('')||'<div class="empty">No pending requests.</div>'}</div></section>`}
