function playerView(){let p=state.players.find(p=>p.id===identity.player_id),ms=active().filter(m=>[m.p1,m.p2].includes(identity.player_id));let response=invitations.find(x=>x.player_id===identity.player_id),invite=new URL(location.href).searchParams.get('join'),wrongInvite=invite&&invite!==String(state.created);return `<div class="player-shell"><div class="player-head"><img src="assets/osp-8-ball.png" alt=""><div><div class="eyebrow">${esc(state.name)}</div><h1>Hello, ${esc(identity.name)}</h1></div>${profileButton()}</div>${wrongInvite?'<div class="notice warn">This invitation belongs to an earlier tournament. The current tournament is shown below.</div>':''}<section class="card" style="margin-bottom:18px"><h2>${esc(state.name)} · Registration</h2><p><strong>${esc(scheduleLabel())}</strong></p><p>${response?.status==='accepted'?'You are registered.':response?.status==='declined'?`You declined: ${esc(response.reason)}`:p?'You are on the player list. Confirm your registration below.':'You have not registered for this tournament yet.'}</p>${!state.rounds.length?`<div class="actions"><button class="btn primary" data-action="respond-invite" data-status="accepted">Join tournament</button><button class="btn ghost" data-action="respond-invite" data-status="declined">Decline with reason</button></div>`:'<p>Registration is closed now that matches have started.</p>'}</section><div class="grid split"><section class="card"><h2>Your next match</h2>${ms.map(m=>`<div class="notice"><h3>${esc(display(m.p1))} vs ${esc(display(m.p2))}</h3><p>${esc(tableName(m.tableId))} · ${esc(roundLabel(m))} · ${m.s1}–${m.s2}</p><div class="actions"><button class="btn primary" data-action="ready" data-id="${m.id}" data-ready="1">I’m here and ready</button><button class="btn" data-action="ready" data-id="${m.id}" data-ready="0">I need more time</button></div></div>`).join('')||'<div class="empty">No match assigned yet. Stay on this page for updates.</div>'}<div class="actions"><button class="btn ghost" data-action="enable-alerts">Enable browser alerts</button></div></section><section class="card"><h2>Your messages</h2><div class="list">${messages.map(m=>`<div class="row"><div class="row-main"><strong>${esc(m.body)}</strong><small>${new Date(m.created_at).toLocaleString()}</small></div></div>`).join('')||'<div class="empty">Messages and match calls appear here.</div>'}</div></section></div><section class="card" style="margin-top:18px"><h2>Your record</h2><p>${p?`Match wins ${stats().find(x=>x.id===p.id)?.wins||0} · losses ${stats().find(x=>x.id===p.id)?.losses||0}`:'Your admin has not linked your player record yet.'}</p></section><section class="card" style="margin-top:18px"><h2>Live standings</h2><div class="list">${rankRows()}</div><h3>Current matches</h3><div class="list">${active().map(m=>`<div class="row"><div class="row-main"><strong>${esc(display(m.p1))} vs ${esc(display(m.p2))}</strong><small>${esc(roundLabel(m))} · ${esc(tableName(m.tableId))} · ${m.s1}–${m.s2}</small></div></div>`).join('')||'<div class="empty">Matches have not been assigned yet.</div>'}</div><h3>Previous tournaments</h3><div class="list">${history.map(h=>{let rows=tournamentStats(h.state),rank=rows.findIndex(x=>x.id===identity.player_id);return `<div class="row"><div class="row-main"><strong>${esc(h.name)}</strong><small>${rank<0?'Did not participate':`Position ${rank+1} of ${rows.length} · ${rows[rank].wins} wins, ${rows[rank].losses} losses`}</small></div></div>`}).join('')||'<div class="empty">No past tournaments yet.</div>'}</div></section></div>`}
async function initialize(){app.innerHTML='<div class="auth-screen">Loading venue…</div>';try{let x=await request('/api/session');identity=x.account;if(!identity){setupInfo=await request('/api/setup');render();return}await bootServer();if(identity.role==='admin')await refreshAccounts();else {invitations=(await request('/api/invitations')).responses;history=(await request('/api/tournaments')).tournaments}await refreshMessages();if(tv)setInterval(()=>{if(tvMode!=='event')return;tvSlide=(tvSlide+1)%4;let host=$('#tv-event-slide');if(host)host.innerHTML=tvEventSlideView()},9000);setInterval(async()=>{if(!dirty)await loadRemote();if(identity?.role==='player'){invitations=(await request('/api/invitations')).responses}else if(identity?.role==='admin'&&tab==='players'){let next=(await request('/api/invitations')).responses;if(JSON.stringify(next)!==JSON.stringify(invitations)){invitations=next;render()}}await refreshMessages()},tv?1500:3500)}catch(e){authError=e.message;render()}}
function setCred(){localStorage.setItem(CKEY,JSON.stringify(creds));}
function display(n){return state.players.find(p=>p.id===n)?.name||'TBD'}function tableName(id){return state.tables.find(t=>t.id===id)?.name||'Unassigned'}function matches(){return state.rounds.flatMap(r=>r.matches)}function active(){return matches().filter(m=>m.p1&&m.p2&&!m.winner)}function atTable(id){return active().find(m=>m.tableId===id)}function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0)}function pool(){return state.prize?state.entry*state.players.length:0}
function isPoints(){return (state.scoring||'games')==='points'}
function stats(){const out=new Map(state.players.map(p=>[p.id,{...p,wins:0,losses:0,gameWins:0,gameLosses:0,balls:0,ballsAgainst:0,racks:0,against:0,streak:0}]));matches().filter(m=>m.winner&&m.p1&&m.p2).forEach(m=>{const w=out.get(m.winner),l=out.get(m.winner===m.p1?m.p2:m.p1);if(w){w.wins++;w.streak++;w.racks+=m.winner===m.p1?m.s1:m.s2;w.against+=m.winner===m.p1?m.s2:m.s1}if(l){l.losses++;l.streak=0;l.racks+=m.winner===m.p1?m.s2:m.s1;l.against+=m.winner===m.p1?m.s1:m.s2}});for(const m of matches())for(const g of m.games||[]){let w=out.get(g.winner),l=out.get(g.loser);if(w)w.gameWins++;if(l)l.gameLosses++;let p1=out.get(m.p1),p2=out.get(m.p2);if(p1){p1.balls+=g.b1;p1.ballsAgainst+=g.b2}if(p2){p2.balls+=g.b2;p2.ballsAgainst+=g.b1}}return [...out.values()].sort((a,b)=>b.wins-a.wins||b.gameWins-a.gameWins||b.balls-a.balls||a.seed-b.seed)}
function tournamentStats(t){let out=(t.players||[]).map(p=>({...p,wins:0,losses:0}));for(const m of (t.rounds||[]).flatMap(r=>r.matches||[])){if(!m.winner||!m.p1||!m.p2)continue;let w=out.find(p=>p.id===m.winner),l=out.find(p=>p.id===(m.winner===m.p1?m.p2:m.p1));if(w)w.wins++;if(l)l.losses++}return out.sort((a,b)=>b.wins-a.wins||a.losses-b.losses||a.seed-b.seed)}
function scheduleLabel(){if(!state.startAt)return 'Date and time not set';let [date,time]=state.startAt.split('T'),[y,m,d]=date.split('-').map(Number),[h,min]=time.split(':').map(Number);let label=new Intl.DateTimeFormat('en-US',{timeZone:'UTC',dateStyle:'full',timeStyle:'short'}).format(new Date(Date.UTC(y,m-1,d,h,min)));return `${label} · ${state.timeZone||'venue time zone'}`}
function invitationURL(){let u=new URL(location.origin+location.pathname);u.searchParams.set('join',String(state.created));return u.toString()}
function invitePanel(){let url=invitationURL(),qr=state.startAt&&window.OSPQR?window.OSPQR(url):'';return `<section class="card invite-card"><h2>Invite players to this tournament</h2><p>${state.startAt?`Starts ${esc(scheduleLabel())}. Share this QR or link; players sign in and join or decline with a reason.`:'Set the tournament date and start time in Tournament setup to send invitations.'}</p>${state.startAt?`<div class="invite-layout"><div class="qr-box">${qr}</div><div><input readonly value="${esc(url)}" aria-label="Invitation link"><div class="actions"><button class="btn primary" data-action="share-invite">Share invitation</button><button class="btn" data-action="copy-invite">Copy link</button></div><p class="inline-help">${state.rounds.length?'Registration closed: matches have started.':'Registration open until the bracket is generated.'}</p></div></div>`:''}<h3>Player responses</h3><div class="list">${roster.filter(a=>a.active).map(a=>{let r=invitations.find(x=>x.player_id===a.player_id);return `<div class="row"><div class="row-main"><strong>${esc(a.name)}</strong><small>${r?.status==='accepted'?'Joined':r?.status==='declined'?`Declined: ${esc(r.reason)}`:state.players.some(p=>p.id===a.player_id)?'On list · confirmation pending':'Awaiting response'}</small></div></div>`}).join('')||'<div class="empty">Add players to your venue roster first.</div>'}</div></section>`}
function assignReadyTables(){const busy=new Set(active().filter(m=>m.tableId).map(m=>m.tableId));for(const t of state.tables){if(busy.has(t.id))continue;const next=active().find(m=>!m.tableId);if(next){next.tableId=t.id;busy.add(t.id)}}}
async function bracket(){if(state.players.length<2)return notify('Add at least two players.');try{const format=state.format||'single',result=format==='triple'?window.OSPTriple.create(state.players):await window.OSPBrackets.create(format,state.players);state.bracketData=format==='triple'?null:result.data;state.tripleData=format==='triple'?result.data:null;state.rounds=result.rounds;state.demo=false;assignReadyTables();save();notify('Matches generated and ready players assigned to tables.')}catch(e){notify('Bracket error: '+e.message)}}
async function changeFormat(format){if(!['single','double','triple','round_robin'].includes(format)||format===state.format)return;if(state.rounds.length){let played=matches().some(m=>m.winner&&m.p1&&m.p2||m.games?.length);if(!confirm(played?'Changing format rebuilds the bracket and removes recorded scores. Export the tournament first if you need those results. Continue?':'Changing format rebuilds the current bracket. Continue?'))return}state.format=format;state.rounds=[];state.bracketData=null;state.tripleData=null;await bracket()}
function propagateByes(){for(let r=0;r<state.rounds.length-1;r++){state.rounds[r].matches.forEach((m,i)=>{if(m.p1&&!m.p2 && r===0)m.winner=m.p1;const next=state.rounds[r+1].matches[Math.floor(i/2)];if(m.winner){if(i%2)next.p2=m.winner;else next.p1=m.winner}})}}
async function finish(id){let m=matches().find(x=>x.id===id);if(!m?.p1||!m?.p2)return null;if(m.s1===m.s2){notify('The match needs a winning score.');return null}if(Math.max(m.s1,m.s2)<state.race){notify(`Target is ${state.race} ${isPoints()?'points':'game wins'}.`);return null}if(m.winner)return null;const winner=m.s1>m.s2?m.p1:m.p2,table=m.tableId;try{if(state.tripleData){const updated=window.OSPTriple.complete(state.tripleData,state.rounds,id,m.s1,m.s2);state.tripleData=updated.data;state.rounds=updated.rounds}else if(state.bracketData){const previous=new Map(matches().map(x=>[x.id,x]));const updated=await window.OSPBrackets.complete(state.bracketData,state.rounds,id,m.s1,m.s2);state.bracketData=updated.data;state.rounds=updated.rounds.map(r=>({...r,matches:r.matches.map(x=>({...x,games:previous.get(x.id)?.games||[],current:previous.get(x.id)?.current||{b1:0,b2:0,winner:null}}))}))}else{let r=state.rounds.findIndex(x=>x.matches.includes(m));m.winner=winner;if(r<state.rounds.length-1){let index=state.rounds[r].matches.indexOf(m),next=state.rounds[r+1].matches[Math.floor(index/2)];if(index%2)next.p2=winner;else next.p1=winner}}assignReadyTables();let completed=matches().find(x=>x.id===id);if(completed)completed.finishedAt=Date.now();const next=active().find(x=>x.tableId===table)||active().find(x=>x.p1===winner||x.p2===winner);save();notify(`${display(winner)} wins the match. ${next?`${display(next.p1)} vs ${display(next.p2)} is next.`:'Waiting for the next pairing.'}`);return{winner,table,nextId:next?.id||null}}catch(e){notify('Could not finish match: '+e.message);return null}}
async function saveGame(id){let m=matches().find(x=>x.id===id);if(!m||m.winner)return;let c=m.current||{b1:0,b2:0,winner:null};if(c.winner!==m.p1&&c.winner!==m.p2)return notify('Mark a game winner before saving.');let b1=Number(c.b1),b2=Number(c.b2);if(!Number.isInteger(b1)||!Number.isInteger(b2)||b1<0||b2<0)return notify('Ball points must be whole numbers of zero or more.');const loser=c.winner===m.p1?m.p2:m.p1;m.games=[...(m.games||[]),{id:uid(),winner:c.winner,loser,b1,b2,at:Date.now()}];if(isPoints()){m.s1+=b1;m.s2+=b2}else if(c.winner===m.p1)m.s1++;else m.s2++;m.current={b1:0,b2:0,winner:null};const reached=Math.max(m.s1,m.s2)>=state.race&&m.s1!==m.s2;if(reached){let result=await finish(id);if(result){transition={...result,gameWinner:c.winner};modal='transition';render()}else save()}else{save();notify(`Game ${m.games.length} saved. Start the next game.`)}}
function headToHead(m){let previous=matches().filter(x=>x.id!==m.id&&x.winner&&x.p1&&x.p2&&[x.p1,x.p2].sort().join('|')===[m.p1,m.p2].sort().join('|'));if(!previous.length)return 'First recorded meeting';let a=previous.filter(x=>x.winner===m.p1).length,b=previous.length-a;return `Previous meetings: ${display(m.p1)} ${a}–${b} ${display(m.p2)}`}
function roundLabel(m){let r=state.rounds.find(x=>x.matches.includes(m));return r?.name||`Round ${state.rounds.indexOf(r)+1}`}
function nav(){return [['overview','◉','Overview'],['bracket','⌗','Bracket & scores'],['players','♟','Players & analysis'],['tables','▦','Tables & cameras'],['settings','⚙','Tournament setup'],['inbox','✉','Messages'],['access','♙','Venue access']].map(([id,icon,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><span class="icon">${icon}</span>${label}</button>`).join('')}
function header(title,sub){return `<div class="top"><div><div class="eyebrow">${esc(state.name)} · ${esc(state.game.toUpperCase())}</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div><div class="top-actions">${profileButton()}<span class="badge ${server?'':'dim'}">${server?'● Shared server':'● Local mode'}</span><button class="btn ghost" data-action="tv">Featured table TV ↗</button><button class="btn ghost" data-action="tv-event">Full event TV ↗</button>${!state.rounds.length?'<button class="btn primary" data-action="bracket">Generate bracket</button>':''}</div></div>`}
function metric(label,val,note){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${val}</div><div class="metric-note">${note||'&nbsp;'}</div></div>`}
function tableCard(t){let m=atTable(t.id),diamonds=Array.from({length:7},(_,i)=>`<i data-number="${i+1}"></i>`).join(''),ends=Array.from({length:3},(_,i)=>`<i data-number="${i+1}"></i>`).join('');return `<div class="table-card"><div class="felt" role="img" aria-label="${esc(t.name)}: billiards table with six pockets and numbered training diamonds"><div class="pockets">${'<i></i>'.repeat(6)}</div><div class="rail-diamonds rail-top">${diamonds}</div><div class="rail-diamonds rail-bottom">${diamonds}</div><div class="rail-diamonds rail-left">${ends}</div><div class="rail-diamonds rail-right">${ends}</div><span class="table-number">${esc(t.name.replace(/\D/g,'')||'•')}</span></div><div class="table-body"><div class="table-head"><h3>${esc(t.name)}</h3><span class="badge ${m?'live':'dim'}">${m?'● In play':'Available'}</span></div><div class="versus">${m?`${esc(display(m.p1))} <em>vs</em> ${esc(display(m.p2))}`:'Ready for next match'}</div><div class="table-meta">${m?`${esc(roundLabel(m))} · ${m.s1} – ${m.s2} · Race to ${state.race}`:'Camera can be connected when assigned'}</div><div class="actions"><button class="btn small" data-action="camera" data-id="${t.id}">Cameras (${angleList(t).length})</button>${m?`<button class="btn small" data-action="match" data-id="${m.id}">Score match</button>`:''}<button class="btn small ghost" data-action="tv-table" data-id="${t.id}">TV view ↗</button></div></div></div>`}
function rankRows(limit=0){let a=stats();if(limit)a=a.slice(0,limit);return a.length?a.map((p,i)=>`<div class="row"><span class="rank">${String(i+1).padStart(2,'0')}</span>${playerAvatar(p.id,p.name)}<div class="row-main"><strong>${esc(p.name)}</strong><small>Matches ${p.wins}–${p.losses} · Games ${p.gameWins}–${p.gameLosses} · Balls ${p.balls}</small></div><span class="badge">${p.wins+p.losses?Math.round(p.wins/(p.wins+p.losses)*100):0}%</span></div>`).join(''):'<div class="empty">Add players to see rankings.</div>'}
function overview(){return header('Tournament command center','Save each game and see which players and tables are next.')+`<div class="grid metrics">${metric('Players',state.players.length,'Registered')}${metric('Live matches',active().filter(m=>m.tableId).length,`${active().length} ready to play`)}${metric('Matches played',matches().filter(m=>m.winner&&m.p2).length,`${matches().filter(m=>m.p1&&m.p2).length} total`)}${metric(state.prize?'Prize pool':'Format',state.prize?money(pool()):({single:'Single elimination',double:'Double elimination',round_robin:'Round robin',triple:'Triple elimination'}[state.format]||'Single elimination'),state.prize?`${money(state.entry)} entry per player`:'No money entry')}</div><div class="grid split"><section class="card"><div class="card-title"><h2>Tables now</h2><button class="btn small ghost" data-tab="tables">Manage tables →</button></div><div class="table-grid">${state.tables.map(tableCard).join('')||'<div class="empty">Add a table in Tournament setup.</div>'}</div></section><section class="card"><div class="card-title"><h2>Player form</h2><button class="btn small ghost" data-tab="players">Full analysis →</button></div><div class="list">${rankRows(6)}</div></section></div><div class="section-title"><div><h2>Upcoming matches</h2><p>Assign a table, then record rack scores as they happen.</p></div></div><div class="grid">${matchList(5)}</div>`}
function matchList(limit=0){let a=active();if(limit)a=a.slice(0,limit);return a.length?a.map(m=>`<div class="row"><div class="row-main"><strong class="match-identities">${playerIdentity(m.p1)}<span class="versus-word">vs</span>${playerIdentity(m.p2)}</strong><small>${esc(tableName(m.tableId))} · ${esc(roundLabel(m))} · ${m.s1}–${m.s2}</small></div><button class="btn small" data-action="match" data-id="${m.id}">Manage</button></div>`).join(''):'<div class="empty">No upcoming matches. Add players and generate a bracket to begin.</div>'}
function bracketView(){return header('Bracket & scores','Save each game to advance the match and schedule the next players.')+`<div class="format-bar"><div class="field"><label for="bracket-format">Elimination format</label><select id="bracket-format">${[['single','Single elimination'],['double','Double elimination'],['triple','Triple elimination'],['round_robin','Round robin']].map(([v,n])=>`<option value="${v}" ${state.format===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn" data-action="change-format">Apply format</button><span class="muted">${state.format==='triple'?'Players exit after three match losses.':'Select the format before generating matches.'}</span></div><div class="notice" style="margin-bottom:17px">${state.rounds.length?'Mark a game winner and save. Reaching the match target advances the winner and frees the table.':'Matches are generated from the player order.'}</div>${state.rounds.length?`<div class="bracket">${state.rounds.map((r,i)=>`<div class="round"><h3>${esc(r.name||`Round ${i+1}`)}</h3>${r.matches.map((m,j)=>`<div class="match ${m.p1&&m.p2&&!m.winner?'live':''}"><div class="match-top"><span>Match ${j+1}</span><span>${esc(tableName(m.tableId))}</span></div><div class="contestant ${m.winner===m.p1?'win':''}">${playerIdentity(m.p1)}<span class="score">${m.p1?m.s1:'—'}</span></div><div class="contestant ${m.winner===m.p2&&m.p2?'win':''}">${playerIdentity(m.p2)}<span class="score">${m.p2?m.s2:'—'}</span></div><div class="actions">${m.p1&&m.p2?`<button class="btn small" data-action="match" data-id="${m.id}">${m.winner?'Result':'Score / assign'}</button>`:m.winner?'<span class="badge dim">Bye</span>':'<span class="muted">Awaiting result</span>'}</div></div>`).join('')}</div>`).join('')}</div>`:'<div class="empty">No bracket yet. Add players, then select Generate bracket.</div>'}`}
function playersView(){return header('Players & analysis','Track match results, individual game wins and losses, and ball points separately.')+`${invitePanel()}<div class="card"><div class="card-title"><h2>Registered players</h2><button class="btn primary" data-action="add-player">+ Add player</button></div><div class="wide-list"><table><thead><tr><th>Rank</th><th>Player</th><th>Match W–L</th><th>Game W–L</th><th>Balls for / against</th><th>Ball difference</th><th>Match win rate</th><th></th></tr></thead><tbody>${stats().map((p,i)=>`<tr><td>${i+1}</td><td><span class="player-identity">${playerAvatar(p.id,p.name)}<span><strong>${esc(p.name)}</strong>${(()=>{let a=accounts.find(x=>x.playerId===p.id);return `<small>${a?`@${esc(a.username)} · ${a.active?'Login active':'Login disabled'}`:'Login account missing'}</small>`})()}</span></span></td><td>${p.wins} – ${p.losses}${state.format==='triple'?` <small>${Math.max(0,3-p.losses)} losses left</small>`:''}</td><td>${p.gameWins} – ${p.gameLosses}</td><td>${p.balls} / ${p.ballsAgainst}</td><td>${p.balls-p.ballsAgainst>0?'+':''}${p.balls-p.ballsAgainst}</td><td><div class="bar"><span style="width:${p.wins+p.losses?Math.round(100*p.wins/(p.wins+p.losses)):0}%"></span></div>${p.wins+p.losses?Math.round(100*p.wins/(p.wins+p.losses)):0}%</td><td><button class="btn small ghost" data-action="edit-player" data-id="${p.id}">Player access</button>${!state.rounds.length?`<button class="btn small danger" data-action="remove-player" data-id="${p.id}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="divider"></div><h3>Add from saved roster</h3><div class="list">${roster.filter(a=>a.active&&!state.players.some(p=>p.id===a.player_id)).map(a=>`<div class="row">${playerAvatar(a.player_id,a.name)}<div class="row-main"><strong>${esc(a.name)}</strong><small>@${esc(a.username)}</small></div><button class="btn small" data-action="enroll-roster" data-id="${esc(a.player_id)}" ${state.rounds.length?'disabled':''}>Add to tournament</button></div>`).join('')||'<div class="empty">All available players are on this tournament list.</div>'}</div><div class="divider"></div><p class="inline-help">Match W–L determines elimination. Game W–L counts saved games; ball points come from the score entered for each saved game. Older results without a game log still count toward match W–L.</p></div>`}
function tablesView(){return header('Tables & cameras','Each table can show several camera angles and its current match.')+`<div class="section-title"><div><h2>Table floor</h2><p>${state.tables.length} tables configured</p></div><button class="btn primary" data-action="add-table">+ Add table</button></div><div class="table-grid">${state.tables.map(tableCard).join('')}</div><div class="notice" style="margin-top:20px">At each table, open its Camera page on the computer attached to that USB camera. Grant browser access, choose the correct devices, and start broadcasting. The TV page can show a selected table video plus live scores. HTTPS is required for camera access.</div>`}
function broadcastPlatform(key,title,defaultServer,dashboard){let b=creds.broadcast||{},v=n=>esc(b[`${key}_${n}`]||'');return `<div class="broadcast-platform"><div class="platform-head"><h3>${title}</h3><a class="btn small ghost" href="${dashboard}" target="_blank" rel="noopener">Open platform ↗</a></div><div class="field"><label>RTMP / RTMPS server URL</label><input name="${key}_server" value="${v('server')||defaultServer}" placeholder="rtmps://..."></div><div class="field"><label>Stream key</label><input name="${key}_streamKey" type="password" value="${v('streamKey')}" autocomplete="off" placeholder="Paste the key from ${title}"></div><div class="field"><label>Public LIVE or event URL</label><input name="${key}_eventUrl" type="url" value="${v('eventUrl')}" placeholder="https://..."></div><div class="field"><label>API key / access token (optional)</label><input name="${key}_apiToken" type="password" value="${v('apiToken')}" autocomplete="off" placeholder="Only if your platform app requires it"></div></div>`}
function broadcastSettings(){let b=creds.broadcast||{},announcement=b.announcement||`${state.name} · ${scheduleLabel()}\nRegister and follow the tournament: ${invitationURL()}`;return `<section class="card broadcast-settings"><div class="card-title"><div><h2>Live streaming & event publishing</h2><p class="inline-help">Configure each destination from its Live dashboard. Keys and API tokens stay only on this administrator device.</p></div><button class="btn ghost" type="button" data-action="toggle-stream-secrets">Show / hide keys</button></div><form id="broadcast-form"><div class="broadcast-grid">${broadcastPlatform('youtube','YouTube','rtmp://a.rtmp.youtube.com/live2','https://studio.youtube.com/')}${broadcastPlatform('facebook','Facebook','rtmps://live-api-s.facebook.com:443/rtmp/','https://www.facebook.com/live/producer/')}${broadcastPlatform('tiktok','TikTok','','https://www.tiktok.com/studio/download')}<div class="broadcast-platform"><div class="platform-head"><h3>Other platform</h3></div><div class="field"><label>Platform name</label><input name="custom_name" value="${esc(b.custom_name||'')}"></div><div class="field"><label>RTMP / RTMPS server URL</label><input name="custom_server" value="${esc(b.custom_server||'')}" placeholder="rtmps://..."></div><div class="field"><label>Stream key</label><input name="custom_streamKey" type="password" value="${esc(b.custom_streamKey||'')}" autocomplete="off"></div><div class="field"><label>Public LIVE or event URL</label><input name="custom_eventUrl" type="url" value="${esc(b.custom_eventUrl||'')}" placeholder="https://..."></div><div class="field"><label>API key / access token (optional)</label><input name="custom_apiToken" type="password" value="${esc(b.custom_apiToken||'')}" autocomplete="off"></div></div></div><div class="divider"></div><div class="field"><label for="event-announcement">Event announcement</label><textarea id="event-announcement" name="announcement" rows="4">${esc(announcement)}</textarea></div><div class="actions" style="margin-top:14px"><button class="btn primary" type="submit">Save streaming setup</button><button class="btn" type="button" data-action="share-event">Share event</button><button class="btn ghost" type="button" data-action="copy-event">Copy announcement</button></div></form><p class="inline-help" style="margin-top:12px">Use OBS or another encoder to send the camera program to the selected RTMP/RTMPS server. TikTok stream keys are available only for eligible accounts.</p></section>`}
function settingsView(){return header('Tournament setup','Set the tournament date, streaming destinations, and start time before inviting players.')+`<div class="grid split"><div class="card"><h2>Event settings</h2><div class="divider"></div><form id="event-form" class="form-grid"><div class="field full"><label for="event-name">Tournament name</label><input id="event-name" name="name" maxlength="80" value="${esc(state.name)}" required></div><div class="field full"><label for="start-at">Tournament date and start time</label><input id="start-at" name="startAt" type="datetime-local" value="${esc(state.startAt||'')}" required><small>Venue time zone: ${esc(state.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'local')}</small></div><div class="field"><label for="game">Pool game</label><select id="game" name="game">${['8-ball','9-ball','10-ball','Straight pool','One pocket','Bank pool','Custom'].map(x=>`<option ${state.game===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="format">Tournament format</label><select id="format" name="format" ${state.rounds.length?'disabled':''}>${[['single','Single elimination'],['double','Double elimination'],['triple','Triple elimination'],['round_robin','Round robin']].map(([v,n])=>`<option value="${v}" ${state.format===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="scoring">Match target type</label><select id="scoring" name="scoring" ${state.rounds.length?'disabled':''}><option value="games" ${!isPoints()?'selected':''}>Game wins</option><option value="points" ${isPoints()?'selected':''}>Ball points</option></select></div><div class="field"><label for="race">Race to (game wins / ball points)</label><input id="race" name="race" type="number" min="1" max="999" value="${state.race}" required></div><div class="field"><label for="entry">Entry amount ($)</label><input id="entry" name="entry" type="number" min="0" step="0.01" value="${state.entry}" ${state.prize?'':'disabled'}></div><div class="field"><label for="prize">Money option</label><select id="prize" name="prize"><option value="0" ${state.prize?'':'selected'}>No money / competition only</option><option value="1" ${state.prize?'selected':''}>Entry and prize pool</option></select></div><div class="full"><button class="btn primary" type="submit">Save settings</button></div></form><div class="divider"></div><div class="actions"><button class="btn" data-action="export">Export data JSON</button><button class="btn" data-action="import">Import JSON</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="btn danger" data-action="new-event">New tournament</button></div><p class="inline-help" style="margin-top:12px">A new tournament archives the current results and keeps this venue’s saved player roster. Entry amount is for display and accounting only; there is no payment processing.</p></div><div class="card"><h2>Shared venue</h2><p class="inline-help">Tournament data and player notices sync across signed-in devices in this venue. Use Venue access to create accounts and Messages to contact players.</p></div></div>${broadcastSettings()}`}
function angleList(t){return t.angles?.length?t.angles:[{id:'main',name:'Main view'}]}
function cameraView(t){if(!t)return header('Table cameras','Add a table to connect cameras.');let m=atTable(t.id);return header(`${esc(t.name)} cameras`,'Attach more than one USB camera to capture different angles of this table.')+`<div class="section-title"><div><h2>Camera angles</h2><p>${angleList(t).length} angles · start each camera separately on the attached computer</p></div><button class="btn primary" data-action="add-angle" data-id="${t.id}">+ Add angle</button></div><div class="camera-grid">${angleList(t).map(angle=>{let key=t.id+'_'+angle.id,online=cameraStreams.has(key);return `<div class="card camera-panel"><div class="card-title"><h3>${esc(angle.name)}</h3><span class="badge ${online?'live':'dim'}">${online?'● Camera on':'Offline'}</span></div><div class="camera-box"><video id="local-${angle.id}" autoplay muted playsinline></video><div class="placeholder" id="placeholder-${angle.id}"><b>◉</b>${esc(angle.name)} camera preview</div></div><div class="form-grid" style="margin-top:14px"><div class="field"><label for="cam-${angle.id}">USB camera</label><select class="camera-device" id="cam-${angle.id}" data-kind="videoinput"><option value="">Default camera</option></select></div><div class="field"><label for="mic-${angle.id}">Microphone</label><select class="camera-device" id="mic-${angle.id}" data-kind="audioinput"><option value="none">No microphone</option><option value="" ${angle.id==='main'?'selected':''}>Default microphone</option></select></div></div><div class="actions" style="margin-top:13px"><button class="btn primary small" data-action="start-camera" data-id="${t.id}" data-angle="${angle.id}">${online?'Switch devices':'Start angle'}</button><button class="btn small" data-action="stop-camera" data-id="${t.id}" data-angle="${angle.id}">Stop</button><button class="btn small ghost" data-action="tv-angle" data-id="${t.id}" data-angle="${angle.id}">View on TV ↗</button>${angle.id!=='main'?`<button class="btn small danger" data-action="remove-angle" data-id="${t.id}" data-angle="${angle.id}">Remove</button>`:''}</div></div>`}).join('')}</div><div class="grid split" style="margin-top:18px"><div class="card"><h2>On this table</h2><div class="divider"></div>${m?`<h3>${esc(display(m.p1))} vs ${esc(display(m.p2))}</h3><p class="muted">${m.s1} – ${m.s2} · Race to ${state.race}</p><div class="actions" style="margin-top:16px"><button class="btn" data-action="match" data-id="${m.id}">Update score</button></div>`:'<div class="empty">No match assigned to this table yet.</div>'}</div><div class="card"><h2>Live production</h2><div class="divider"></div><p class="inline-help">The TV display selects one table and one angle at a time. Keep this page open while broadcasting. The microphone on an angle carries live commentary with that view. Camera access needs HTTPS, and restrictive networks may need a TURN relay.</p></div></div>`}
function tvAlertContent(){let notices=messages.filter(m=>m.account_id==null&&['ready','registration','announcement'].includes(m.kind)).slice(0,3),latest=matches().filter(m=>m.winner&&m.p1&&m.p2).sort((a,b)=>(b.finishedAt||b.games?.at(-1)?.at||0)-(a.finishedAt||a.games?.at(-1)?.at||0))[0],result=latest?`<span class="tv-alert-item"><b>FINAL RESULT</b> ${esc(display(latest.winner))} wins · ${esc(display(latest.p1))} ${Number(latest.s1)||0}–${Number(latest.s2)||0} ${esc(display(latest.p2))}</span>`:'';return [result,...notices.map(m=>`<span class="tv-alert-item"><b>${m.kind==='ready'?'PLAYER READY':m.kind==='registration'?'REGISTRATION':'NOTICE'}</b> ${esc(m.body)}</span>`)].filter(Boolean).join('<span class="tv-alert-separator">✦</span>')||'<span class="tv-alert-item"><b>LIVE UPDATES</b> Match calls and player responses appear here as they arrive.</span>'}
function tvAnnouncementView(){let announcement=state.tvAnnouncement;if(!announcement?.text&&!announcement?.imageId)return '';return `<div class="tv-broadcast-announcement" role="status">${announcement.imageId&&/^[a-f0-9-]{36}$/.test(announcement.imageId)?`<img src="/api/tv-image/${esc(announcement.imageId)}" alt="Tournament announcement image">`:''}${announcement.text?`<strong>${esc(announcement.text)}</strong>`:''}</div>`}
function tvEventSlideView(){let live=active().filter(m=>m.tableId),waiting=active().filter(m=>!m.tableId),rank=stats(),recent=matches().filter(m=>m.winner&&m.p1&&m.p2).sort((a,b)=>(b.finishedAt||b.games?.at(-1)?.at||0)-(a.finishedAt||a.games?.at(-1)?.at||0)).slice(0,4),target=Math.max(1,Number(state.race)||1);let intro=`<div class="tv-event-content tv-event-intro"><div class="tv-event-eyebrow">OFFICIAL TOURNAMENT BROADCAST</div><img src="assets/osp-8-ball.png" alt="OSP Billiards Play"><h2>${esc(state.name)}</h2><div class="tv-event-sub">${esc(state.game.toUpperCase())} · ${esc(state.format?.replaceAll('_',' ')||'Tournament')} · Race to ${esc(state.race)}</div><div class="tv-event-big-metrics"><div><b>${state.players.length}</b><span>PLAYERS</span></div><div><b>${state.tables.length}</b><span>TABLES</span></div><div><b>${matches().filter(m=>m.winner).length}</b><span>RESULTS</span></div></div><p>${state.startAt?`Starts ${esc(state.startAt.replace('T',' '))}${state.timeZone?' · '+esc(state.timeZone):''}`:'Stand by for the next match assignments'}</p></div>`;let scores=`<div class="tv-event-content"><div class="tv-event-eyebrow">LIVE SCORES · ${live.length} TABLE${live.length===1?'':'S'}</div><h2>On the tables</h2><div class="tv-event-score-grid">${live.map(m=>`<div class="tv-event-score-card"><div class="tv-event-card-label">${esc(tableName(m.tableId))} · ${esc(roundLabel(m))}</div><div class="tv-event-competitor"><strong>${esc(display(m.p1))}</strong><b>${Number(m.s1)||0}</b></div><div class="tv-event-progress"><i style="width:${Math.min(100,Math.max(0,(Number(m.s1)||0)/target*100))}%"></i></div><div class="tv-event-competitor"><strong>${esc(display(m.p2))}</strong><b>${Number(m.s2)||0}</b></div><div class="tv-event-progress"><i style="width:${Math.min(100,Math.max(0,(Number(m.s2)||0)/target*100))}%"></i></div></div>`).join('')||'<div class="tv-event-blank">Matches and scores appear when the first players are assigned.</div>'}</div></div>`;let bracket=`<div class="tv-event-content"><div class="tv-event-eyebrow">TOURNAMENT PROGRESS</div><h2>Road to the final</h2><div class="tv-event-rounds">${state.rounds.map((r,i)=>`<div class="tv-event-round"><h3>${esc(r.name||`Round ${i+1}`)}</h3>${r.matches.slice(0,5).map(m=>`<div class="tv-event-pair"><span>${esc(display(m.p1))} <small>vs</small> ${esc(display(m.p2))}</span><strong>${m.winner?`★ ${esc(display(m.winner))}`:m.tableId?esc(tableName(m.tableId)):'Waiting'}</strong></div>`).join('')||'<div class="tv-event-blank">Awaiting matches</div>'}</div>`).join('')||'<div class="tv-event-blank">The bracket will appear when the administrator starts the tournament.</div>'}</div></div>`;let leaders=`<div class="tv-event-content"><div class="tv-event-eyebrow">LEADERS & NEXT MATCHES</div><h2>Who is advancing?</h2><div class="tv-event-two-col"><div><h3>Standings</h3>${rank.slice(0,5).map((x,i)=>`<div class="tv-event-line"><b>${i+1}. ${esc(x.name)}</b><span>${x.wins} W · ${x.losses} L</span></div>`).join('')||'<div class="tv-event-blank">Players will appear here.</div>'}</div><div><h3>Coming up</h3>${waiting.slice(0,4).map(m=>`<div class="tv-event-line"><b>${esc(display(m.p1))} vs ${esc(display(m.p2))}</b><span>${m.tableId?esc(tableName(m.tableId)):'Table pending'}</span></div>`).join('')||recent.map(m=>`<div class="tv-event-line"><b>★ ${esc(display(m.winner))}</b><span>${Number(m.s1)||0}–${Number(m.s2)||0} · ${esc(roundLabel(m))}</span></div>`).join('')||'<div class="tv-event-blank">Next pairings appear when they are ready.</div>'}</div></div></div>`;return [intro,scores,bracket,leaders][tvSlide%4]+`<div class="tv-event-dots">${[0,1,2,3].map(i=>`<i class="${i===tvSlide%4?'active':''}"></i>`).join('')}</div>`}
function tvView(){let t=state.tables.find(x=>x.id===selectedTvTable)||state.tables[0],m=t&&atTable(t.id),angles=t?angleList(t):[],selected=angles.find(x=>x.id===selectedTvAngle)||angles[0],live=active().filter(x=>x.tableId),waiting=active().filter(x=>!x.tableId),recent=matches().filter(x=>x.winner&&x.p1&&x.p2).sort((a,b)=>(b.finishedAt||b.games?.at(-1)?.at||0)-(a.finishedAt||a.games?.at(-1)?.at||0)).slice(0,4),ranking=stats().slice(0,5),limit=state.format==='triple'?3:state.format==='double'?2:state.format==='single'?1:Infinity;return `<div class="tv tv-broadcast"><div class="tv-head"><div><div class="eyebrow">OSP BILLIARDS · TOURNAMENT LIVE</div><h1>${esc(state.name)}</h1><div class="tv-event-meta">${esc(state.game.toUpperCase())} · ${esc(state.format?.replaceAll('_',' ')||'Tournament')} · Race to ${esc(state.race)}</div></div><img src="assets/osp-8-ball.png" alt="OSP eight ball logo"></div><div class="tv-grid"><section class="tv-stage">${tvMode==='event'?`<div class="tv-event-stage"><div id="tv-event-slide">${tvEventSlideView()}</div>${tvAnnouncementView()}</div>`:`<div class="camera-box tv-camera"><video id="remote-video" autoplay playsinline controls></video><div class="placeholder" id="remote-placeholder"><b>◉</b>${t?`Waiting for ${esc(t.name)} · ${esc(selected?.name||'camera')}`:'No tables configured'}</div><span class="tv-live-label"><i></i> LIVE · ${esc(t?.name||'TABLE')}</span><div class="tv-score-overlay" aria-live="polite"><div class="tv-round-label">${m?`${esc(roundLabel(m))} · ${esc(t.name)} · ${esc(state.scoring==='points'?'Ball points':'Games won')}`:'FEATURED TABLE · AWAITING NEXT MATCH'}</div><div class="tv-score-line"><div class="tv-side ${m?.s1>m?.s2?'ahead':''}">${m?`${playerAvatar(m.p1,display(m.p1))}<span>${esc(display(m.p1))}</span>`:'<span>Waiting for players</span>'}</div><div class="tv-digits">${m?`${Number(m.s1)||0}<em>:</em>${Number(m.s2)||0}`:'– <em>:</em> –'}</div><div class="tv-side tv-side-right ${m?.s2>m?.s1?'ahead':''}">${m?`<span>${esc(display(m.p2))}</span>${playerAvatar(m.p2,display(m.p2))}`:'<span>Next match</span>'}</div></div><div class="tv-score-foot">${m?`Game ${(m.games?.length||0)+1} · ${esc(state.scoring==='points'?'Points target':'Race')} ${esc(state.race)}`:'Live scores update when a game is saved'}</div></div>${tvAnnouncementView()}</div>`}<div class="tv-controls"><div class="field"><label for="tv-mode">TV presentation</label><select id="tv-mode"><option value="table" ${tvMode==='table'?'selected':''}>Featured table</option><option value="event" ${tvMode==='event'?'selected':''}>Full event</option></select></div><div class="field"><label for="tv-select">Featured table</label><select id="tv-select">${state.tables.map(x=>`<option value="${esc(x.id)}" ${t?.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label for="tv-angle">Camera angle</label><select id="tv-angle">${angles.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><button class="btn ghost small" data-action="fullscreen">Full screen ⛶</button><button class="btn ghost small" data-action="admin">← Control panel</button></div></section><aside class="tv-sidepanel"><section class="tv-panel"><div class="tv-panel-heading"><span class="tv-kicker">ON THE TABLES</span><strong>${live.length} LIVE</strong></div><div class="tv-board-list">${live.map(x=>`<div class="tv-board-row ${x.tableId===t?.id?'featured':''}"><span class="tv-table-name">${esc(tableName(x.tableId))} <small>${esc(roundLabel(x))}</small></span><div><strong>${esc(display(x.p1))}</strong><small>VS</small><strong>${esc(display(x.p2))}</strong></div><b class="tv-row-score">${Number(x.s1)||0}<span> : </span>${Number(x.s2)||0}</b></div>`).join('')||'<div class="tv-empty">Waiting for the first match to be assigned.</div>'}</div></section><section class="tv-panel"><div class="tv-panel-heading"><span class="tv-kicker">UP NEXT</span><strong>${waiting.length} READY</strong></div><div class="tv-board-list">${waiting.slice(0,5).map(x=>`<div class="tv-next-row"><div><strong>${esc(display(x.p1))} <span>vs</span> ${esc(display(x.p2))}</strong><small>${esc(roundLabel(x))}</small></div><span class="tv-table-tag">${x.tableId?esc(tableName(x.tableId)):'Table pending'}</span></div>`).join('')||'<div class="tv-empty">Upcoming matches will appear when both players advance. Table assignments appear as soon as a table is free.</div>'}</div></section><section class="tv-panel"><div class="tv-panel-heading"><span class="tv-kicker">LATEST RESULTS</span><strong>${recent.length} FINAL</strong></div><div class="tv-board-list">${recent.map(x=>`<div class="tv-result-row"><span class="tv-result-winner">★ ${esc(display(x.winner))}</span><span>${esc(roundLabel(x))} · ${esc(display(x.p1))} ${Number(x.s1)||0}–${Number(x.s2)||0} ${esc(display(x.p2))}</span></div>`).join('')||'<div class="tv-empty">Results will appear after the first completed match.</div>'}</div></section><section class="tv-panel"><div class="tv-panel-heading"><span class="tv-kicker">PLAYER STANDINGS</span><strong>W–L</strong></div><div class="tv-board-list">${ranking.map((x,i)=>`<div class="tv-standing"><span class="tv-standing-place">${String(i+1).padStart(2,'0')}</span>${playerAvatar(x.id,x.name)}<strong>${esc(x.name)}</strong><small>${x.wins}–${x.losses}</small><span class="tv-standing-status ${x.losses>=limit?'out':''}">${x.losses>=limit?'Eliminated':x.wins?'Advancing':'In play'}</span></div>`).join('')||'<div class="tv-empty">Add players to display standings.</div>'}</div></section></aside></div><div class="tv-ticker" aria-label="Tournament announcements"><span class="tv-ticker-label">TOURNAMENT UPDATES</span><div class="tv-ticker-window"><div class="tv-ticker-track" id="tv-alerts">${tvAlertContent()}</div></div></div></div>`}
function modalView(){if(!modal)return '';let content='';if(modal==='player')content=`<h2>${pendingPlayerRequest?'Create player from request':'Add player'}</h2>${pendingPlayerRequest?`<p class="inline-help">Review the submitted details, choose an initial password and give it to the player securely. Their email and phone will be saved in their profile.</p>`:''}<form id="player-form"><div class="field"><label for="player-name">Player name</label><input id="player-name" name="name" maxlength="70" required autofocus value="${esc(pendingPlayerRequest?.name||'')}" placeholder="e.g. Alex Morgan"></div><div class="field"><label>Login username</label><input name="username" required pattern="[-._a-zA-Z0-9]{3,40}" value="${esc(pendingPlayerRequest?.username||'')}" autocapitalize="none"></div><div class="field"><label>Email (optional)</label><input name="email" type="email" value="${esc(pendingPlayerRequest?.email||'')}"></div><div class="field"><label>Phone (optional)</label><input name="phone" type="tel" value="${esc(pendingPlayerRequest?.phone||'')}"></div><div class="field"><label>Initial password (8+ characters)</label><input name="password" type="password" minlength="8" required autocomplete="new-password"></div><div class="actions"><button class="btn primary" type="submit">Create player & login</button><button class="btn ghost" type="button" data-action="close">Cancel</button></div></form>`;if(modal==='edit-player'){let p=state.players.find(x=>x.id===editingPlayer),account=accounts.find(x=>x.playerId===editingPlayer);content=`<h2>Player access</h2><p class="inline-help">Review and update this player's login. Leave New password empty to keep the current password.</p><form id="player-access-form"><input type="hidden" name="playerId" value="${esc(p?.id||'')}"><input type="hidden" name="accountId" value="${esc(account?.id||'')}"><div class="field"><label>Player name</label><input name="name" value="${esc(p?.name||account?.name||'')}" maxlength="70" required></div><div class="field"><label>Username</label><input name="username" value="${esc(account?.username||'')}" pattern="[-._a-zA-Z0-9]{3,40}" required autocapitalize="none"></div><div class="field"><label>Email (optional)</label><input name="email" type="email" value="${esc(account?.email||'')}"></div><div class="field"><label>Phone (optional)</label><input name="phone" type="tel" value="${esc(account?.phone||'')}"></div><div class="field"><label>${account?'New password (leave empty to keep current)':'Initial password (8+ characters)'}</label><input name="password" type="password" minlength="8" ${account?'':'required'} autocomplete="new-password"></div>${account?`<div class="field"><label>Login access</label><select name="active"><option value="1" ${account.active?'selected':''}>Active</option><option value="0" ${account.active?'':'selected'}>Disabled</option></select></div><div class="notice">Current login: <strong>@${esc(account.username)}</strong> · ${account.active?'Active':'Disabled'}</div>`:'<div class="notice warn">This player has no login account yet. Saving will create it.</div>'}<div class="actions"><button class="btn primary">${account?'Save access':'Create player login'}</button><button type="button" class="btn ghost" data-action="close">Cancel</button></div></form>`}if(modal==='angle')content=`<h2>Add camera angle</h2><form id="angle-form"><div class="field"><label for="angle-name">Angle name</label><input id="angle-name" name="name" maxlength="35" required placeholder="e.g. Overhead, side, close-up"></div><div class="actions"><button class="btn primary" type="submit">Add angle</button><button class="btn ghost" type="button" data-action="close">Cancel</button></div></form>`;if(modal==='table')content=`<h2>Add table</h2><form id="table-form"><div class="field"><label for="table-name">Table name</label><input id="table-name" name="name" maxlength="35" required value="Table ${state.tables.length+1}"></div><div class="actions"><button class="btn primary" type="submit">Add table</button><button class="btn ghost" type="button" data-action="close">Cancel</button></div></form>`;
if(modal==='profile'){let person=profileData||identity,photo=identity.avatarVersion?`<img src="/api/profile/photo?v=${identity.avatarVersion}" alt="Profile photo">`:esc((identity.name||'?').trim().charAt(0).toUpperCase());content=`<div class="profile-detail"><div class="profile-photo">${photo}</div><div><div class="eyebrow">${identity.role==='player'?'PLAYER':'ADMINISTRATOR / GROUP MANAGER'}</div><h2>My profile</h2><strong>${esc(person.name||identity.name)}</strong><p class="muted">@${esc(person.username||identity.username)}</p></div></div><div class="profile-info">${person.email?`<div>Email <strong>${esc(person.email)}</strong></div>`:''}${person.phone?`<div>Phone <strong>${esc(person.phone)}</strong></div>`:''}</div><div class="field"><label for="profile-photo">Add your photo or logo (PNG, JPEG, WebP · up to 2 MB)</label><input id="profile-photo" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="actions"><button class="btn primary" data-action="open-practice">🎱 8-Ball training</button>${identity.avatarVersion?'<button class="btn ghost" data-action="remove-profile-photo">Remove photo</button>':''}<button class="btn danger" data-action="logout">Sign out</button><button class="btn ghost" data-action="close">Close</button></div>`}
if(modal==='practice')content=practiceView();
if(modal==='match'){let m=matches().find(x=>x.id===editingMatch);if(!m)return '';let locked=!!m.winner,c=m.current||{b1:0,b2:0,winner:null};const playerRow=(side)=>{let id=side===1?m.p1:m.p2,balls=side===1?c.b1:c.b2;return `<div class="game-player"><div class="game-player-head"><strong>${esc(display(id))}</strong><span>${c.winner===id?'WIN':c.winner?'LOSS':'Choose result'}</span></div><div class="game-player-controls"><div class="field"><label for="balls-${side}">Ball points</label><div class="ball-input"><button type="button" data-action="ball-step" data-side="${side}" data-delta="-1" ${locked?'disabled':''}>−</button><input id="balls-${side}" data-ball-side="${side}" type="number" min="0" max="9999" value="${balls||0}" ${locked?'disabled':''}><button type="button" data-action="ball-step" data-side="${side}" data-delta="1" ${locked?'disabled':''}>+</button></div></div><button class="btn ${c.winner===id?'primary':''}" data-action="game-winner" data-side="${side}" ${locked?'disabled':''}>${c.winner===id?'✓ Won game':'Mark win'}</button></div></div>`};content=`<div class="eyebrow">${esc(roundLabel(m))} · ${esc(tableName(m.tableId))}</div><h2>${esc(display(m.p1))} vs ${esc(display(m.p2))}</h2><p class="inline-help" style="margin-top:9px">${esc(headToHead(m))}${['single','double','triple'].includes(state.format)?` · Elimination losses: ${stats().find(x=>x.id===m.p1)?.losses||0} / ${stats().find(x=>x.id===m.p2)?.losses||0}`:''}</p><div class="match-progress"><span>${isPoints()?'Ball points':'Games won'}: <strong>${m.s1} – ${m.s2}</strong></span><span>Target ${state.race} · Game ${(m.games?.length||0)+1}</span></div><div class="field" style="margin-bottom:14px"><label for="match-table">Playing on</label><select id="match-table" ${locked?'disabled':''}><option value="">Unassigned</option>${state.tables.map(t=>`<option value="${t.id}" ${m.tableId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>${locked?`<div class="notice">Match won by ${esc(display(m.winner))}. The next ready players have been assigned to a free table.</div>`:`<div class="game-entry">${playerRow(1)}${playerRow(2)}</div><p class="inline-help">Mark one winner; the other player is recorded with a loss for this game. Ball points stay separate from game wins.</p>`}${m.games?.length?`<div class="divider"></div><h3>Saved games</h3><div class="game-history">${m.games.map((g,i)=>`<div class="row"><span>Game ${i+1} · ${esc(display(g.winner))} won</span><strong>Balls ${g.b1}–${g.b2}</strong></div>`).join('')}</div>`:''}<div class="actions">${!locked?`<button class="btn primary" data-action="save-game" data-id="${m.id}">Save game & next →</button>`:''}<button class="btn ghost" data-action="close">Close</button></div>`}
if(modal==='transition'){let next=matches().find(m=>m.id===transition?.nextId);content=`<div class="eyebrow">Game saved · Match complete</div><h2>${esc(display(transition?.winner))} advances</h2><div class="notice">${next?`Next on ${esc(tableName(next.tableId))}: <strong>${esc(display(next.p1))} vs ${esc(display(next.p2))}</strong>.`:'The table is free. The next pairing will be assigned when the other required results arrive.'}</div><div class="actions">${next?`<button class="btn primary" data-action="open-next" data-id="${next.id}">Open next match →</button>`:''}<button class="btn ghost" data-action="close">Close</button></div>`}
return `<div class="modal-bg" id="modal-bg"><div class="modal ${modal==='practice'?'practice-modal':''}" role="dialog" aria-modal="true">${content}</div></div>`}
function render(){if(!identity){app.innerHTML=authView();return}if(!remoteLoaded){app.innerHTML='<div class="auth-screen">Loading venue…</div>';return}if(identity.role==='player'){app.innerHTML=playerView()+modalView();return}if(tv){let video=$('#remote-video');app.innerHTML=tvView();if(tvMode==='event'){if(viewerTable)connectViewer('');return}let fresh=$('#remote-video');if(video&&fresh)fresh.replaceWith(video);if(remoteStream){let v=$('#remote-video');if(v){v.srcObject=remoteStream;$('#remote-placeholder').style.display='none'}}let t=state.tables.find(x=>x.id===$('#tv-select')?.value),a=angleList(t||{angles:[]}).find(x=>x.id===$('#tv-angle')?.value)||angleList(t||{angles:[]})[0];let room=t?`${t.id}_${a.id}`:'';if(viewerTable!==room)connectViewer(room);return}let title={overview:overview,bracket:bracketView,players:playersView,tables:tablesView,settings:settingsView,inbox:inboxView,access:accessView};let cameraTab=tab.startsWith('camera:');app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/osp-8-ball.png" alt="OSP logo"><div><strong>OSP BILLIARDS</strong><small>PLAY / CONTROL</small></div></div><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="side-bottom"><div>${esc(identity.name)} · ${esc(identity.username)}</div><button class="btn small ghost" data-action="logout">Sign out</button><br><b>● ${server?'Venue sync active':'Local preview'}</b><br>${server?'Changes are shared with your venue.':'Changes are saved on this device.'}</div></aside><main class="main">${cameraTab?cameraView(state.tables.find(x=>x.id===tab.split(':')[1])||state.tables[0]):(title[tab]||overview)()}</main></div>${modalView()}`;for(const [key,stream] of cameraStreams){let angle=key.split('_').pop(),video=$('#local-'+angle),placeholder=$('#placeholder-'+angle);if(video){video.srcObject=stream;if(placeholder)placeholder.style.display='none'}}if(cameraTab)enumerate();if(modal==='player')$('#player-name')?.focus()}
function openTv(id,angle,mode='table'){let u=new URL(location.href);u.search='?view=tv'+(mode==='event'?'&mode=event':'')+(id?'&table='+encodeURIComponent(id):'')+(angle?'&angle='+encodeURIComponent(angle):'');window.open(u.toString(),'_blank','noopener')}
async function bootServer(){let x=await request('/api/state');state=x.state;revision=x.rev;server=true;remoteLoaded=true;render()}
async function loadRemote(){if(polling||dirty||!identity||modal==='practice')return;polling=true;try{let x=await request('/api/state');if(x.rev>revision){state=x.state;revision=x.rev;if(!(tab==='inbox'&&app.querySelector('#tv-announcement-form')?.contains(document.activeElement)))render()}}catch{}finally{polling=false}}
async function sync(){if(!server||identity?.role!=='admin'||syncInFlight)return;syncInFlight=true;let snapshot=JSON.stringify(state);try{let x=await request('/api/state','PUT',{state:JSON.parse(snapshot),rev:revision});revision=x.rev;dirty=JSON.stringify(state)!==snapshot;if(dirty){clearTimeout(syncTimer);syncTimer=setTimeout(sync,350)}}catch(e){notify(e.message);dirty=false;await loadRemote()}finally{syncInFlight=false}}
