bindPracticeCanvas=function(){bindPracticeCanvasPrecision();let canvas=$('#practice-canvas'),consoleEl=$('.aim-console');if(!canvas||!consoleEl)return;if(!$('#practice-spin-tools')){let actions=consoleEl.querySelector('.practice-shot-actions');actions?.insertAdjacentHTML('beforebegin',`<div class="spin-aim-tools" id="practice-spin-tools"><div class="cue-spin-control"><div class="spin-title">BALL 16 CONTACT</div><div class="cue-ball-pad" id="cue-ball-pad" aria-label="Choose where the cue hits the cue ball"><span id="cue-spin-dot"></span><i class="spin-top">FOLLOW</i><i class="spin-bottom">DRAW</i></div><small id="cue-spin-label">CENTER · NO SPIN</small></div><div class="cue-rotor-control"><span>CUE ROTOR <b id="cue-rotor-value">${practiceAim.toFixed(1)}°</b></span><div id="cue-rotor" class="cue-rotor" role="slider" tabindex="0" aria-label="Precise cue angle" aria-valuemin="0" aria-valuemax="359.9" aria-valuenow="${practiceAim.toFixed(1)}"><span class="cue-rotor-track"><i class="cue-rotor-thumb"></i></span></div><small>Hold and drag · release to lock the cue</small></div></div>`)}let pad=$('#cue-ball-pad'),dot=$('#cue-spin-dot'),spinLabel=$('#cue-spin-label'),rotor=$('#cue-rotor'),rotorValue=$('#cue-rotor-value');const spinName=()=>Math.abs(practiceSpinX)<.12&&Math.abs(practiceSpinY)<.12?'CENTER · NO SPIN':`${practiceSpinY<-.12?'FOLLOW':practiceSpinY>.12?'DRAW':'POSITION'}${practiceSpinX<-.12?' · LEFT':practiceSpinX>.12?' · RIGHT':''}`;const paintSpin=()=>{if(dot){dot.style.left=`${50+practiceSpinX*34}%`;dot.style.top=`${50+practiceSpinY*34}%`}if(spinLabel)spinLabel.textContent=spinName()};const setSpin=e=>{e.preventDefault();let r=pad.getBoundingClientRect(),x=((e.clientX-r.left)/r.width-.5)*2,y=((e.clientY-r.top)/r.height-.5)*2,m=Math.hypot(x,y);if(m>1){x/=m;y/=m}practiceSpinX=Math.round(x*20)/20;practiceSpinY=Math.round(y*20)/20;paintSpin()};if(pad){pad.onpointerdown=e=>{pad.setPointerCapture?.(e.pointerId);setSpin(e)};pad.onpointermove=e=>{if(pad.hasPointerCapture?.(e.pointerId))setSpin(e)};pad.onpointerup=pad.onpointercancel=e=>pad.releasePointerCapture?.(e.pointerId);pad.ondblclick=()=>{practiceSpinX=practiceSpinY=0;paintSpin()}}if(rotor){const paintRotor=()=>{let angle=practiceAim.toFixed(1);rotor.style.setProperty('--rotor-position',(practiceAim/359.9*100)+'%');rotor.setAttribute('aria-valuenow',angle);if(rotorValue)rotorValue.textContent=angle+'°'},rotate=e=>{e.preventDefault();let rect=rotor.getBoundingClientRect(),position=Math.max(0,Math.min(1,(e.clientX-rect.left)/Math.max(1,rect.width)));practiceAim=Math.round(position*3599)/10;paintRotor();bindPracticeCanvas()};paintRotor();rotor.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();practiceRotorPointer=e.pointerId;rotor.setPointerCapture?.(e.pointerId);rotate(e)};rotor.onpointermove=e=>{if(practiceRotorPointer!==e.pointerId)return;if(e.pointerType==='mouse'&&!(e.buttons&1)){practiceRotorPointer=null;return}rotate(e)};rotor.onpointerup=e=>{if(practiceRotorPointer!==e.pointerId)return;rotate(e);practiceRotorPointer=null;rotor.releasePointerCapture?.(e.pointerId)};rotor.onpointercancel=e=>{if(practiceRotorPointer===e.pointerId)practiceRotorPointer=null;rotor.releasePointerCapture?.(e.pointerId)};rotor.onkeydown=e=>{let change=e.key==='ArrowLeft'||e.key==='ArrowDown'?-1:e.key==='ArrowRight'||e.key==='ArrowUp'?1:0;if(!change&&e.key!=='Home'&&e.key!=='End')return;e.preventDefault();practiceAim=e.key==='Home'?0:e.key==='End'?359.9:Math.max(0,Math.min(359.9,Math.round((practiceAim+change*(e.shiftKey?1:.1))*10)/10));paintRotor();bindPracticeCanvas()}}paintSpin();let fire=practiceShootNow;if(!fire)return;practiceShootNow=()=>{let wasActive=practiceShotActive,shotAngle=practiceAim,spinX=practiceSpinX,spinY=practiceSpinY;fire();if(wasActive||!practiceShotActive)return;let run=++practiceSpinRun,dir={x:Math.cos(-shotAngle*Math.PI/180),y:Math.sin(-shotAngle*Math.PI/180)},applied=false;const assist=()=>{if(run!==practiceSpinRun||!practiceGame)return;let cue=practiceGame.balls[0];for(const ball of practiceGame.balls){if(ball.pocketed)continue;for(const [px,py] of [[36,36],[450,28],[864,36],[36,414],[450,422],[864,414]])if(Math.hypot(ball.x-px,ball.y-py)<25){ball.pocketed=true;ball.vx=ball.vy=0;break}}if(practiceShotActive&&!applied&&cue&&!cue.pocketed){let contact=practiceGame.balls.slice(1).some(ball=>!ball.pocketed&&Math.hypot(ball.x-cue.x,ball.y-cue.y)<24.5);if(contact){cue.vx+=dir.x*(-spinY*8)+(-dir.y)*(spinX*5.5);cue.vy+=dir.y*(-spinY*8)+dir.x*(spinX*5.5);applied=true}}if(practiceShotActive)requestAnimationFrame(assist)};requestAnimationFrame(assist)}};
